ST.xhtml:
parts.camera();
stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := parts.camera.stat.health = HealthStatus.good,
    hasWarning := parts.camera.stat.health = HealthStatus.warning);
stat.busy := F_BusyStatus(
    superState := TRUE,
    isBusy := parts.camera.stat.busy = BusyStatus.busy);
proc.initialize( isEnabled := (NOT(stat.init = InitializationStatus.locked)) AND ((stat.init = InitializationStatus.shutdown) OR ((stat.init = InitializationStatus.initializingFailed) OR (stat.init = InitializationStatus.initialized))) );
proc.reset( isEnabled := TRUE );
proc.acquireTarget( isEnabled := TRUE );
proc.startGuiding();
proc.stop( isEnabled := TRUE );
proc.setCameraParamSet( isEnabled := TRUE );

IF do_request THEN
    do_request_result := request( vMag := set.vMag );
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.vMag := vMag;
THIS^.stat.busy := BusyStatus.busy;
THIS^.stat.health := HealthStatus.good;

IF THIS^.stat.enabled = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start( vMag := vMag );
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request( vMag := set.vMag );
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.vMag := vMag;
THIS^.stat.busy := BusyStatus.busy;
THIS^.stat.health := HealthStatus.good;

IF THIS^.stat.enabled = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start( vMag := vMag );
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request( paramSet := set.paramSet );
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.paramSet := paramSet;
THIS^.stat.busy := BusyStatus.busy;
THIS^.stat.health := HealthStatus.good;

IF THIS^.stat.enabled = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start( paramSet := paramSet );
ELSE
    request := RequestResults.REJECTED;
END_IF;
